import { NotFoundException } from '@nestjs/common';
import { CustomerService } from './customer/customer.service';
import { BillingService } from './billing/billing.service';
import { SchedulerService } from './scheduler/scheduler.service';
import { UsageService } from './usage/usage.service';
import { AuditService } from './audit/audit.service';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from './scheduler/dto/scheduler.dto';
import { paymentChannel } from './customer/dto/create-customer.dto';

const fakePoint = () => {
    const p: any = {
        tag: () => p,
        stringField: () => p,
        floatField: () => p,
        booleanField: () => p,
        intField: () => p,
        timestamp: () => p,
    };
    return p;
};

const influxMock = () =>
    ({
        loadPoints: jest.fn().mockResolvedValue(undefined),
        getPoint: jest.fn(() => fakePoint()),
        getInvoicesForCustomer: jest.fn().mockResolvedValue([]),
    } as any);

describe('tmp migration behaviour', () => {
    it('create only schedules billing when the customer has an offering', async () => {
        const scheduler = { create: jest.fn().mockResolvedValue({}), remove: jest.fn() } as any;
        const service = new CustomerService(influxMock(), scheduler, {} as any, {} as any, {} as any);

        await service.create(
            { customerName: 'a', email: 'a@b.c', paymentChannel: paymentChannel.Stripe, businessID: 'biz' } as any,
            'sub-1'
        );
        expect(scheduler.create).not.toHaveBeenCalled();

        const { customerId } = await service.create(
            {
                customerName: 'a',
                email: 'a@b.c',
                paymentChannel: paymentChannel.Stripe,
                businessID: 'biz',
                offeringId: 'off-1',
            } as any,
            'sub-1'
        );
        expect(scheduler.create).toHaveBeenCalledWith({
            schedulerID: customerId,
            schedulerType: schedulerType.billing,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: { customerId, businessID: 'biz' },
            rate: SupportedMeasurementFrequencies.monthly,
            subject: 'sub-1',
            businessID: 'biz',
        });
    });

    it('update replaces the schedule when the offering changes and tolerates a missing schedule', async () => {
        const scheduler = {
            create: jest.fn().mockResolvedValue({}),
            remove: jest.fn().mockRejectedValue(new NotFoundException('nope')),
        } as any;
        const service = new CustomerService(influxMock(), scheduler, {} as any, {} as any, {} as any);
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: 'cust-1', customerName: 'a', paymentChannel: paymentChannel.Stripe } as any],
            message: 'Found Customer',
        });

        await service.update({ customerId: 'cust-1', businessID: 'biz', offeringId: 'off-1', subject: 'sub-2' } as any);
        expect(scheduler.remove).toHaveBeenCalledWith({
            schedulerID: 'cust-1',
            businessID: 'biz',
            isBillingQueue: true,
        });
        expect(scheduler.create).toHaveBeenCalledWith(
            expect.objectContaining({
                schedulerID: 'cust-1',
                businessID: 'biz',
                subject: 'sub-2',
                rate: SupportedMeasurementFrequencies.monthly,
                schedulerType: schedulerType.billing,
                scheduleParameters: { customerId: 'cust-1', businessID: 'biz' },
            })
        );
    });

    it('update leaves the schedule alone when the offering is unchanged', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn() } as any;
        const service = new CustomerService(influxMock(), scheduler, {} as any, {} as any, {} as any);
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [
                {
                    customerId: 'cust-1',
                    customerName: 'a',
                    paymentChannel: paymentChannel.Stripe,
                    offeringId: 'off-1',
                } as any,
            ],
            message: 'Found Customer',
        });
        await service.update({ customerId: 'cust-1', businessID: 'biz', offeringId: 'off-1' } as any);
        expect(scheduler.create).not.toHaveBeenCalled();
        expect(scheduler.remove).not.toHaveBeenCalled();
    });

    it('billing job uses businessID from the record and customerId from the parameters', async () => {
        const influx = influxMock();
        const invoices = { generateInvoiceForUsageTotal: jest.fn().mockResolvedValue({ invoiceId: 'inv-9' }) } as any;
        const customers = {
            findOne: jest.fn().mockResolvedValue({
                data: [{ customerId: 'cust-1', offering: { billingCycle: 'monthly' } }],
                message: 'Found Customer',
            }),
        } as any;
        const service = new BillingService(influx, invoices, customers);
        await service.create({
            data: { businessID: 'biz', scheduleParameters: { customerId: 'cust-1' } },
        } as any);
        expect(customers.findOne).toHaveBeenCalledWith({ customerId: 'cust-1', businessID: 'biz' });
        const call = invoices.generateInvoiceForUsageTotal.mock.calls[0][0];
        expect(call.businessID).toBe('biz');
        expect(call.customerId).toBe('cust-1');
        expect(typeof call.start).toBe('string');
        expect(typeof call.end).toBe('string');
        expect(influx.loadPoints).toHaveBeenCalled();
        const tags: string[] = [];
        // verify invoiceId got into the record
        influx.getPoint = jest.fn();
        expect(invoices.generateInvoiceForUsageTotal).toHaveBeenCalledTimes(1);
        expect(tags).toEqual([]);
    });

    it('billing job reports failures to the audit channel and does not persist', async () => {
        const influx = influxMock();
        const invoices = {
            generateInvoiceForUsageTotal: jest.fn().mockRejectedValue(new Error('boom')),
        } as any;
        const customers = {
            findOne: jest.fn().mockResolvedValue({
                data: [{ customerId: 'cust-1', offering: { billingCycle: 'monthly' } }],
                message: 'Found Customer',
            }),
        } as any;
        const publish = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
        const service = new BillingService(influx, invoices, customers);
        await expect(
            service.create({ data: { businessID: 'biz', scheduleParameters: { customerId: 'cust-1' } } } as any)
        ).resolves.toBeUndefined();
        expect(publish).toHaveBeenCalled();
        expect(influx.loadPoints).not.toHaveBeenCalled();
        publish.mockRestore();
    });

    it('billing job skips customers without an offering', async () => {
        const influx = influxMock();
        const invoices = { generateInvoiceForUsageTotal: jest.fn() } as any;
        const customers = {
            findOne: jest.fn().mockResolvedValue({ data: [{ customerId: 'cust-1' }], message: 'Found Customer' }),
        } as any;
        const service = new BillingService(influx, invoices, customers);
        await service.create({ data: { businessID: 'biz', scheduleParameters: { customerId: 'cust-1' } } } as any);
        expect(invoices.generateInvoiceForUsageTotal).not.toHaveBeenCalled();
        expect(influx.loadPoints).not.toHaveBeenCalled();
    });

    it('emitOne routes billing to the billing queue and everything else to the scheduler queue', async () => {
        const queue = { add: jest.fn() } as any;
        const billingQueue = { add: jest.fn() } as any;
        const service = new SchedulerService(queue, billingQueue);
        await service.emitOne({
            schedulerId: 'sch-1',
            payload: { schedulerType: schedulerType.billing, businessID: 'biz', scheduleParameters: { c: 1 } },
        });
        expect(billingQueue.add).toHaveBeenCalledWith('billingReport', expect.objectContaining({ businessID: 'biz' }));
        expect(queue.add).not.toHaveBeenCalled();

        await service.emitOne({
            schedulerId: 'sch-2',
            payload: {
                schedulerType: schedulerType.dimensionDataGathering,
                dimensionType: 'ebsVolume',
                businessID: 'biz',
            },
        });
        expect(queue.add).toHaveBeenCalledWith('ebsVolume', expect.objectContaining({ businessID: 'biz' }));
    });

    it('usage read returns empty when the customer has no offering', async () => {
        const customers = {
            findOne: jest.fn().mockResolvedValue({ data: [{ customerId: 'cust-1' }], message: 'Found Customer' }),
        } as any;
        const service = new UsageService({} as any, {} as any, {} as any, customers, {} as any);
        await expect(service.findUsageForCustomer({ customerId: 'cust-1', businessID: 'biz' }, {})).resolves.toEqual([]);
    });
});

