    expect(influx.loadPoints).toHaveBeenCalled();
    const tags: Record<string, string> = {};
    const capture: any = {
        tag: (k: string, v: string) => {
            tags[k] = v;
            return capture;
        },
        stringField: () => capture,
    };
    influx.getPoint = jest.fn(() => capture);
    invoices.generateInvoiceForUsageTotal.mockClear();
    influx.loadPoints.mockClear();
    await service.create({
        data: { businessID: 'biz', scheduleParameters: { customerId: 'cust-1' } },
    } as any);
    expect(tags.invoiceId).toBe('inv-9');
    expect(tags.customerId).toBe('cust-1');
    expect(tags.businessID).toBe('biz');
    expect(tags.startTime).toEqual(expect.any(String));
    expect(tags.endTime).toEqual(expect.any(String));
    expect(influx.loadPoints).toHaveBeenCalledWith(expect.any(String), 'paigo', [capture]);
});

arguments.oldString:
    expect(influx.loadPoints).toHaveBeenCalled();
    const tags: string[] = [];
    // verify invoiceId got into the record
    influx.getPoint = jest.fn();
    expect(invoices.generateInvoiceForUsageTotal).toHaveBeenCalledTimes(1);
    expect(tags).toEqual([]);
});
